function [safe,latched,flags] = bezpecnostne_meranie_v06(T1lag,T2lag,prev,raw)
%#codegen
% V06: 2 meracie vetvy s vlastnym oneskorenim, bez pristupu k T_true.
% raw: 1:11 prevadzka, 12/13 bias senzorov, 14 flow, 15 E-STOP,
% 16 manual reset, 17 stuck valve, 18 rejection cooling availability.
safe=zeros(1,11);
for k=1:11,safe(k)=raw(k);end
t1=T1lag+raw(12);
t2=T2lag+raw(13);
valid=isfinite(t1)&&isfinite(t2);
mismatch=valid&&(abs(t1-t2)>0.35);
hot=valid&&((t1>=27.70)||(t2>=27.70));
flowFault=raw(14)<0.5;
estop=raw(15)>0.5;
fault=(~valid)||mismatch||hot||flowFault||estop;
latched=double(prev>0.5);
resetOK=0;
% Failure dominates simultaneous reset request.
if fault
    latched=1;
elseif raw(16)>0.5 && latched>0.5 && max(t1,t2)<=27.65
    latched=0;resetOK=1;
end
if latched>0.5,safe(9)=0;end
flags=zeros(1,10);
flags(1)=latched;flags(2)=double(mismatch);
flags(3)=double(hot);flags(4)=double(flowFault);
flags(5)=double(estop);flags(6)=double(~valid);
flags(7)=resetOK;flags(8)=t1;flags(9)=t2;
flags(10)=safe(9);
end

function y=fyzikalne_ochrany_v07(core,Tpool,raw,Tit)
%#codegen
% Separatne dve uzatvaracie vetvy HX: fyzicky unik len pri dvoch poruchach.
% REJECT A =180 kW, REJECT B=150 kW; oba su scenarove hodnoty.
% raw 17 primary stuck, 19 secondary stuck, 18 main reject availability,
% 20 backup reject availability. raw 22 = Q_IT_load_avoided (W).
dt=900; Cw=997*500*4182; Cit=8e6;
Qcmd=max(0,core(4));
QrejectCmd=max(0,core(17));
Qdc=max(0,core(18));
primaryFault=raw(17)>0.5;
backupFault=raw(19)>0.5;
leak=0;
if primaryFault && backupFault && Qcmd<=1e-7
    drive=max(0,raw(2)-Tpool-3);
    leak=min([25000,QrejectCmd,4500*drive]);
end
Qremaining=max(0,QrejectCmd-leak);
mainCap=180000*min(1,max(0,raw(18)));
backupCap=150000*min(1,max(0,raw(20)));
QrejectA=min(Qremaining,mainCap);
QrejectB=min(max(0,Qremaining-QrejectA),backupCap);
Qreject=QrejectA+QrejectB;
Qunhandled=max(0,Qremaining-Qreject);
passive=max(0,2000*(Tit-30));
TitNext=max(30,Tit+dt*(Qunhandled-passive)/Cit);
y=zeros(1,39);
for k=1:25,y(k)=core(k);end
y(1)=core(1)+dt*leak/Cw;
y(4)=Qcmd+leak;
y(6)=core(6)+leak;
y(17)=Qreject;
% Include accumulated, not-dissipated heat explicitly in closure
y(22)=Qdc-(y(6)+core(14)+Qreject+Qunhandled);
y(24)=y(4)-(y(6)+core(7));
y(26)=leak;
y(27)=Qunhandled;
y(28)=TitNext;
y(29)=double(TitNext>=42); 
y(30)=QrejectCmd;
y(31)=Qreject;
y(32)=double((Qcmd<=1e-7)&&(leak>0));
y(33)=y(22);
y(34)=QrejectA;
y(35)=QrejectB;
y(36)=max(0,raw(22)); % avoided modeled waste heat
y(37)=double(primaryFault);
y(38)=double(backupFault);
y(39)=Qremaining-(QrejectA+QrejectB+Qunhandled);
end

function y=uprava_zataze_IT_v07(Tit,raw)
%#codegen
% Nova ochrana; redukcia zataze IT pri strate OBOCH chladiacich vetiev.
% 21 vstupov, Q_DC je dostupne odpadove teplo [W], nie elektricka energia.
% 21: povolena automaticka redukcia IT zataze [0/1].
y=zeros(1,22);
for k=1:21
    y(k)=raw(k);
end
shed=0;
if (raw(18)<0.5) && (raw(20)<0.5) && raw(21)>0.5 && Tit>=38
    shed=0.70*max(0,raw(1)); % scenarovy okamzity pokles o 70%
    y(1)=max(0,raw(1)-shed);
end
y(22)=shed;
end

function y = alokuj_teplo_v04_sk(T,E,ziad,straty,rezim,u)
%#codegen
% Stav T [C], energia TES E[J], ziad/straty [W], rezim Stateflow 0..4.
% Tepelny zdroj DC: len skutocne dostupny tok, nikdy IT nominal.
dt=900; C=997*500*4182;
Emax=900*3.6e6; % 900 kWh
eta_c=0.93; eta_d=0.91;
Qdc=max(0,u(1)); Tdc=u(2); Qdhneed=max(0,u(3));
TES_ok=u(10)>0.5;
Qtesloss=0.002*max(0,E)/86400;
Qdirect=0; QhpPool=0; QhpDH=0; Qcharge=0; Qdis=0;
QhpSrc=0; Pel=0; Paux=0; cop=0;
if (rezim==1) && u(11)>0.5 && u(9)>0.5
    % 5 K approach; konduktancia je predpoklad, nie navrh doskoveho HX.
    Qhxmax=max(0,8500*(Tdc-T-5));
    Qdirect=min([ziad,Qdc,150000,Qhxmax]);
end
Qleft=max(0,Qdc-Qdirect);
if rezim==1 || rezim==2
    % T kondenzatora 52 C, T vyparnika Tdc-5 C; Carnot * 0.43.
    % Bez manufacturer COP(Tsource,Tsink,PLR) = iba scenar.
    Tevap=Tdc-5; Tcond=52;
    cop=min(6,max(2.5,0.43*(Tcond+273.15)/max(5,Tcond-Tevap)));
    QhpCap=min([200000,55000*cop,Qleft/max(1e-9,1-1/cop)]);
    % Minimalna priorita tepelnej siete: rezervuj max 50 kW.
    minDH=min(Qdhneed,min(50000,QhpCap));
    QhpPool=min(max(0,ziad-Qdirect),max(0,QhpCap-minDH));
    QhpDH=min(Qdhneed,QhpCap-QhpPool);
    spare=max(0,QhpCap-QhpPool-QhpDH);
    extraPool=min(max(0,ziad-Qdirect-QhpPool),spare);
    QhpPool=QhpPool+extraPool;
    spare=max(0,QhpCap-QhpPool-QhpDH);
    % Nabijame TES az po aktualnom bazene a obsluhe siete.
    if TES_ok && E<Emax && spare>0
        room=max(0,(Emax-E+Qtesloss*dt)/(eta_c*dt));
        Qcharge=min([spare,70000,room]);
    end
    QhpOut=QhpPool+QhpDH+Qcharge;
    Pel=QhpOut/cop;
    QhpSrc=QhpOut-Pel;
    if QhpOut>0,Paux=1500;end
end
if Qdirect>0,Paux=Paux+500;end
Qpool=Qdirect+QhpPool;
QdhShort=max(0,Qdhneed-QhpDH);
if TES_ok && QdhShort>0 && E>0
    transferable=max(0,(E-Qtesloss*dt)*eta_d/dt);
    Qdis=min([QdhShort,80000,transferable]);
    if Qdis>0,Paux=Paux+250;end
end
% TES nesmie sucasne nabijat a vybijat.
if Qdis>0 && Qcharge>0
    Qcharge=0;
    QhpOut=QhpPool+QhpDH;
    Pel=QhpOut/cop;
    QhpSrc=QhpOut-Pel;
end
Qdh=QhpDH+Qdis;
Qreject=max(0,Qdc-Qdirect-QhpSrc);
Enext=max(0,min(Emax,E+dt*(eta_c*Qcharge-Qdis/eta_d-Qtesloss)));
Tnext=T+dt*(Qpool-straty)/C;
qsourceResidual=Qdc-(Qdirect+QhpSrc+Qreject);
qhpResidual=(QhpPool+QhpDH+Qcharge)-(QhpSrc+Pel);
qpoolResidual=Qpool-(Qdirect+QhpPool);
qdhResidual=Qdh-(QhpDH+Qdis);
y=zeros(1,25);
y(1)=Tnext;
y(2)=Enext;
y(3)=ziad;
y(4)=Qpool;
y(5)=straty;
y(6)=Qdirect;
y(7)=QhpPool;
y(8)=QhpDH;
y(9)=Qcharge;
y(10)=Qdis;
y(11)=Qdh;
y(12)=max(0,Qdhneed-Qdh);
y(13)=max(0,ziad-Qpool);
y(14)=QhpSrc;
y(15)=Pel;
y(16)=Paux;
y(17)=Qreject;
y(18)=Qdc;
y(19)=cop;
y(20)=rezim;
y(21)=Qtesloss;
y(22)=qsourceResidual;
y(23)=qhpResidual;
y(24)=qpoolResidual;
y(25)=qdhResidual;
end

function [ziad,straty,stav_novy] = vypocitaj_dopyt_bazena_sk(T,stav,u)
%#codegen
% u [Qdc_W,Tdc_C,Qdh_W,Tair_C,RH,aktivita,plachta,IT_ok,BAZEN_ok,TES_ok,HX_ok].
% Vykony W, teploty C, krok 900 s, objem 500 m3.
A=312.5; C=997*500*4182; dt=900; cp=4182;
Ta=u(4);rh=min(1,max(0,u(5)));
activity=max(0,u(6));cover=min(1,max(0,u(7)));
pv=0.61094*exp(17.625*T/(T+243.04));
pa=rh*0.61094*exp(17.625*Ta/(Ta+243.04));
mv=max(0,4e-5*A*(pv-pa)*activity*(1-0.9*cover));
Qevap=mv*2440000;
Qconv=3*A*(T-Ta)*(1-0.75*cover);
Qrad=0.95*5.670374419e-8*A*((T+273.15)^4-(Ta-2+273.15)^4)*(1-0.75*cover);
Qkonstr=800*(T-20);
Qmakeup=mv*cp*(T-15);
straty=Qevap+Qconv+Qrad+Qkonstr+Qmakeup+2000;
stav_novy=stav;
if T<=27.35,stav_novy=1;elseif T>=27.65,stav_novy=0;end
if u(9)<0.5
    stav_novy=0;
end
ziad=0;
if stav_novy>0.5 && T<27.75 && u(9)>0.5
    Qsafe=max(0,(27.75-T)*C/dt+straty);
    Qset=max(0,(27.58-T)*C/dt+straty);
    ziad=min([150000,Qsafe,Qset]);
end
end
